<source_code>
#include <iostream>
#include <fstream>
#include <algorithm>
#include <unordered_map>

using namespace std;

typedef long long LL;

LL puteri[20];

int solve( LL number, int pos )
{
   LL contor = number / puteri[pos];

   if ( number % puteri[pos] == 0 )
            return pos * contor;

   int a = pos * contor + solve( number % puteri[pos], pos - 1 );
   int b = pos * ( contor + 1 ) + solve( puteri[pos] - ( number % puteri[pos] ), pos - 1 );

   return min( a, b );
}

int main()
{
    puteri[1] = 1;

    for ( int i = 2; i <= 17; ++i )
    {
        puteri[i] = puteri[i - 1] * 10LL + 1;
    }

    LL n;

    cin >> n;
    cout << solve( n, 17 );

    return 0;
}

